#include "../v7/search.h"
#include <climits>
using namespace v2;
int main(int argc,char**argv){try{if(argc!=6)throw std::runtime_error("BASE MODE SEED COUNT OUTPUT");init();Learner m;m.load(argv[1]);std::string mode=argv[2];int depth=mode=="exact4"?4:3;Search s(m);s.maxNodes=mode=="current3"?24000:INT_MAX;uint32_t first=std::stoul(argv[3]);int n=std::stoi(argv[4]);std::ofstream out(argv[5]);for(int i=0;i<n;i++){RNG rng{first+uint32_t(i)};Game g;g.reset(rng);auto c=opening(g);uint64_t nodes=0;int depths[5]{};auto start=std::clock();while(!g.over&&high(g.b)<12&&g.turns<6000){auto a=s.choose(g.b,g.next,c,depth);if(a.direction<0||(! (mode=="current3")&&s.completed!=depth))throw std::runtime_error("incomplete search");nodes+=s.nodes;depths[s.completed]++;g.advance(move(g.b,a.direction),rng);c=observe(c,g.next);}if(!g.over&&high(g.b)<12)throw std::runtime_error("truncated");out<<"{\"seed\":"<<first+i<<",\"success\":"<<(high(g.b)>=12?"true":"false")<<",\"moves\":"<<g.turns<<",\"nodes\":"<<nodes<<",\"cpu\":"<<double(std::clock()-start)/CLOCKS_PER_SEC<<",\"depths\":["<<depths[1]<<','<<depths[2]<<','<<depths[3]<<','<<depths[4]<<"]}"<<std::endl;}}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
